
const WORDS=[{"id": 0, "w": "消失", "p": "xiāoshī", "t": "动词", "m": "biến mất, mất đi", "coll": "逐渐消失、消失不见", "s": "太阳升起来以后，山间的雾渐渐消失了。"}, {"id": 1, "w": "洪水", "p": "hóngshuǐ", "t": "名词", "m": "lũ, nước lũ", "coll": "发生洪水、洪水灾害", "s": "连续几天的大雨使这条河附近的村庄遭遇了洪水。"}, {"id": 2, "w": "地震", "p": "dìzhèn", "t": "名词", "m": "động đất", "coll": "发生地震、地震救援", "s": "地震发生以后，救援人员立即赶到现场，帮助受困的居民。"}, {"id": 3, "w": "破坏", "p": "pòhuài", "t": "动词", "m": "phá hoại, làm tổn hại", "coll": "破坏环境、破坏平衡", "s": "游客在欣赏风景的时候，不应该破坏当地的自然环境。"}, {"id": 4, "w": "砍", "p": "kǎn", "t": "动词", "m": "chặt, bổ", "coll": "砍树、砍木头", "s": "为了保护森林，当地居民不再随意砍树。"}, {"id": 5, "w": "生存", "p": "shēngcún", "t": "动词", "m": "sinh tồn, sống còn", "coll": "生存环境、难以生存", "s": "如果河水受到严重污染，很多鱼类就难以在这里生存。"}, {"id": 6, "w": "沙漠", "p": "shāmò", "t": "名词", "m": "sa mạc", "coll": "沙漠地区、穿过沙漠", "s": "进入沙漠以前，旅行者需要准备足够的饮用水。"}, {"id": 7, "w": "公布", "p": "gōngbù", "t": "动词", "m": "công bố", "coll": "公布结果、公布数据", "s": "调查结束以后，有关部门向公众公布了结果。"}, {"id": 8, "w": "数据", "p": "shùjù", "t": "名词", "m": "dữ liệu, số liệu", "coll": "统计数据、分析数据", "s": "研究人员正在仔细分析这次调查收集到的数据。"}, {"id": 9, "w": "真实", "p": "zhēnshí", "t": "形容词", "m": "chân thực, đúng sự thật", "coll": "真实情况、真实故事", "s": "这部电影是根据一个真实的故事改编的。"}, {"id": 10, "w": "夸张", "p": "kuāzhāng", "t": "形容词 / 动词", "m": "phóng đại, nói quá; khoa trương", "coll": "夸张的说法、毫不夸张", "s": "他说一天能读完十本书，大家都觉得这种说法有些夸张。"}, {"id": 11, "w": "资源", "p": "zīyuán", "t": "名词", "m": "tài nguyên, nguồn lực", "coll": "自然资源、节约资源", "s": "我们应该从小事做起，养成节约资源的良好习惯。"}, {"id": 12, "w": "车祸", "p": "chēhuò", "t": "名词", "m": "tai nạn xe cộ, tai nạn giao thông", "coll": "发生车祸、避免车祸", "s": "为了避免车祸，司机开车时必须集中注意力。"}, {"id": 13, "w": "不安", "p": "bù'ān", "t": "形容词", "m": "bất an, lo lắng", "coll": "感到不安、令人不安", "s": "一直没有收到朋友的消息，她心里越来越不安。"}, {"id": 14, "w": "工业", "p": "gōngyè", "t": "名词", "m": "công nghiệp", "coll": "工业发展、工业生产", "s": "这座城市正在努力减少工业生产带来的污染。"}, {"id": 15, "w": "农业", "p": "nóngyè", "t": "名词", "m": "nông nghiệp", "coll": "农业生产、现代农业", "s": "这些新的技术已经广泛应用于当地的农业生产。"}, {"id": 16, "w": "生产", "p": "shēngchǎn", "t": "动词", "m": "sản xuất", "coll": "生产产品、生产过程", "s": "这家工厂主要生产可以重复使用的环保袋。"}, {"id": 17, "w": "大型", "p": "dàxíng", "t": "形容词", "m": "cỡ lớn, quy mô lớn", "coll": "大型设备、大型活动", "s": "参加这次大型活动的游客很多，工作人员提前做好了准备。"}, {"id": 18, "w": "工厂", "p": "gōngchǎng", "t": "名词", "m": "nhà máy, xưởng", "coll": "一家工厂、工厂设备", "s": "这家工厂安装了新的设备，用来处理生产过程中产生的废水。"}, {"id": 19, "w": "废", "p": "fèi", "t": "形容词", "m": "phế, thải; không còn dùng được", "coll": "废纸、废水", "s": "这些用过的废纸经过处理以后，还可以重新利用。"}, {"id": 20, "w": "燃烧", "p": "ránshāo", "t": "动词", "m": "cháy, đốt cháy", "coll": "燃烧煤炭、燃烧过程", "s": "干燥的树枝一接触火苗，就迅速燃烧起来。"}, {"id": 21, "w": "煤炭", "p": "méitàn", "t": "名词", "m": "than đá", "coll": "煤炭资源、运输煤炭", "s": "这列货运火车主要负责向附近城市运输煤炭。"}, {"id": 22, "w": "密切", "p": "mìqiè", "t": "形容词 / 动词", "m": "mật thiết, chặt chẽ; làm gắn bó hơn", "coll": "密切相关、密切配合", "s": "我们的身体健康与周围的生活环境密切相关。"}, {"id": 23, "w": "尾气", "p": "wěiqì", "t": "名词", "m": "khí thải của động cơ, khí thải xe cộ", "coll": "汽车尾气、减少尾气排放", "s": "减少私家车的使用，可以帮助减少汽车尾气的排放。"}, {"id": 24, "w": "幸运", "p": "xìngyùn", "t": "形容词", "m": "may mắn", "coll": "十分幸运、幸运的是", "s": "她很幸运，在暴雨来临以前，已经安全回到了家。"}, {"id": 25, "w": "敏感", "p": "mǐngǎn", "t": "形容词", "m": "nhạy cảm", "coll": "对气味敏感、敏感的话题", "s": "她对气味十分敏感，房间里有一点烟味，就能马上察觉。"}, {"id": 26, "w": "自觉", "p": "zìjué", "t": "形容词 / 副词", "m": "tự giác, chủ động làm điều nên làm", "coll": "自觉遵守、自觉行动", "s": "参加活动的同学都能自觉遵守规定，不随意丢弃垃圾。"}, {"id": 27, "w": "设施", "p": "shèshī", "t": "名词", "m": "cơ sở vật chất, công trình và trang thiết bị", "coll": "公共设施、环保设施", "s": "新建的公园配有完善的公共设施，方便居民休闲锻炼。"}, {"id": 28, "w": "能源", "p": "néngyuán", "t": "名词", "m": "năng lượng, nguồn năng lượng", "coll": "清洁能源、能源消耗", "s": "这家企业计划使用更多清洁能源，减少对传统燃料的依赖。"}, {"id": 29, "w": "逐步", "p": "zhúbù", "t": "副词", "m": "từng bước, dần dần theo từng bước", "coll": "逐步完善、逐步扩大", "s": "学校计划分几个阶段，逐步完善校园里的垃圾分类设施。"}, {"id": 30, "w": "尽量", "p": "jǐnliàng", "t": "副词", "m": "cố gắng hết mức, trong khả năng có thể", "coll": "尽量减少、尽量节约", "s": "在日常生活中，我们应该尽量减少一次性用品的使用。"}, {"id": 31, "w": "私人", "p": "sīrén", "t": "形容词", "m": "cá nhân, tư nhân, riêng tư", "coll": "私人空间、私人财产", "s": "即使是关系很好的朋友，也应该尊重彼此的私人空间。"}, {"id": 32, "w": "尊敬", "p": "zūnjìng", "t": "动词", "m": "kính trọng, tôn kính", "coll": "尊敬长辈、令人尊敬", "s": "这位老师认真负责，一直受到学生们的尊敬。"}, {"id": 33, "w": "鼓舞", "p": "gǔwǔ", "t": "动词 / 形容词", "m": "cổ vũ, khích lệ, làm phấn chấn", "coll": "鼓舞人心、受到鼓舞", "s": "听到项目取得进展的消息，大家都受到了鼓舞，对未来更有信心。"}, {"id": 34, "w": "消极", "p": "xiāojí", "t": "形容词", "m": "tiêu cực, thiếu chủ động", "coll": "消极态度、消极应对", "s": "面对困难时，我们应该主动寻找办法，而不是消极等待。"}, {"id": 35, "w": "幻想", "p": "huànxiǎng", "t": "动词 / 名词", "m": "ảo tưởng, tưởng tượng xa rời thực tế", "coll": "不切实际的幻想、充满幻想", "s": "如果只是幻想成功，却从不付诸行动，就很难实现目标。"}, {"id": 36, "w": "贡献", "p": "gòngxiàn", "t": "动词 / 名词", "m": "đóng góp, cống hiến; sự đóng góp", "coll": "做出贡献、贡献力量", "s": "参加志愿活动，是我们为社区做出贡献的一种方式。"}, {"id": 37, "w": "命运", "p": "mìngyùn", "t": "名词", "m": "số phận, vận mệnh", "coll": "改变命运、共同命运", "s": "他相信，坚持学习和努力工作能够改变自己的命运。"}, {"id": 38, "w": "掌握", "p": "zhǎngwò", "t": "动词", "m": "nắm vững; nắm giữ, kiểm soát", "coll": "掌握知识、掌握技术", "s": "通过反复练习，她终于掌握了这项新技术。"}];
